const { execFileSync } = await import('child_process');
const { mkdtempSync, mkdirSync, writeFileSync, rmSync } = await import('fs');
const { tmpdir } = await import('os');
const { join } = await import('path');
const root = $root;
const cli = root + '/packages/main/dist/cli.js';
const dir = mkdtempSync(join(tmpdir(), 'koala-phase-advance-'));
try {
  mkdirSync(join(dir, 'docs', 'story', 'actives'), { recursive: true });
  mkdirSync(join(dir, 'docs', 'requirements'), { recursive: true });
  writeFileSync(join(dir, 'koala.config.json'), JSON.stringify({ scanRoot: 'packages/main', rootDir: 'src', outDir: 'packages/main/dist', testsDir: 'packages/main/tests', fixturesDir: 'packages/main/tests/fixtures', storyDir: 'docs/story/actives', requirementsDir: 'docs/requirements', storyPrefix: 'B' }, null, 2));
  execFileSync('git', ['init'], { cwd: dir, stdio: ['pipe','pipe','pipe'] });
  execFileSync('git', ['config', 'user.name', 'Koala Test'], { cwd: dir, stdio: ['pipe','pipe','pipe'] });
  execFileSync('git', ['config', 'user.email', 'koala@example.com'], { cwd: dir, stdio: ['pipe','pipe','pipe'] });
  writeFileSync(join(dir, '.gitignore'), 'node_modules\n');
  execFileSync('git', ['add', '.'], { cwd: dir, stdio: ['pipe','pipe','pipe'] });
  execFileSync('git', ['commit', '-m', 'init'], { cwd: dir, stdio: ['pipe','pipe','pipe'] });
  const created = execFileSync('node', [cli, '--root', dir, 'story_create', JSON.stringify({ name: 'phase-advance-codes', title: 'Phase advance codes', description: 'tmp', type: 'feature', priority: 'high', checklist: [{ title: 'x', context: 'x' }] })], { cwd: root, encoding: 'utf8', stdio: ['pipe','pipe','pipe'] });
  const storyId = created.match(/B-[a-f0-9]+/)?.[0];
  execFileSync('node', [cli, '--root', dir, 'story_advance', JSON.stringify({ storyId, phase: 'INIT_CHECK' })], { cwd: root, encoding: 'utf8', stdio: ['pipe','pipe','pipe'] });
  const wt = join(dir, '.worktrees', storyId);
  execFileSync('node', [cli, '--root', dir, 'story_advance', JSON.stringify({ storyId, phase: 'PLAN' })], { cwd: wt, encoding: 'utf8', stdio: ['pipe','pipe','pipe'] });
  try {
    execFileSync('node', [cli, '--root', dir, 'story_advance', JSON.stringify({ storyId, phase: 'DEV' })], { cwd: wt, encoding: 'utf8', stdio: ['pipe','pipe','pipe'] });
    return { hasPrefix: false, hasBoth: false };
  } catch (error) {
    const text = String(error.stdout || '') + String(error.stderr || '');
    return { hasPrefix: text.includes('Reason code:'), hasBoth: text.includes('[missing_test_intent_happy]') && text.includes('[missing_story_review]') };
  }
} finally { rmSync(dir, { recursive: true, force: true }); }

